from p"benchmark_harness.jo" import clock
kernel=(values:array<int64> indices:IntRange):>int64=>{
let checksum:int64=0
loop round in [0..20) {
    let picked=values[indices]
    checksum+=picked[round]+picked[picked.length-1]
}
return checksum
}
main=():>void=>{
let values=[loop i in [0..1000000) i]
let indices=[0,2..1000000)
if kernel(values indices) not=? 20000340 panic("warmup checksum")
let started=clock() let checksum=kernel(values indices) let elapsed=clock()-started
printl"{checksum} {elapsed}"
}

