import hashlib
import json
import os
import statistics
import subprocess
from pathlib import Path

root=Path.cwd()
directory=Path('/tmp/dewy-source-core/range-index-benchmark')
report=json.loads(Path('/tmp/dewy-source-core/range-index-runtime.json').read_text())
baseline=root/'__dewycache__/compact-core/build-1792258623730140477/bin/dewy-core'
state=json.loads((root/'__dewycache__/compact-core/current.json').read_text())
candidate=root/'__dewycache__/compact-core'/state['binary']
env={k:v for k,v in os.environ.items() if not k.startswith(('DEWY_', 'SLOPPY_'))}
env['SLOPPY_EMIT_WORKERS']='1'
paired={'samples':7,'clock':'Linux thread CPU','load_start':os.getloadavg(),
        'scope':report['scope'],'expected_checksum':report['expected_checksum'],
        'harness_sha256':report['harness_sha256'],'compilers':{},'workloads':{}}
for label,compiler in [('baseline',baseline),('candidate',candidate)]:
    paired['compilers'][label]={'path':str(compiler),'sha256':hashlib.sha256(compiler.read_bytes()).hexdigest()}
for name in ['range','index_array']:
    source=directory/f'{name}.dewy'
    binaries={}
    for label,compiler in [('baseline',baseline),('candidate',candidate)]:
        binary=directory/f'paired-{label}-{name}'
        run=subprocess.run([str(compiler),'build',str(source),'--release','-o',str(binary)],capture_output=True,text=True,timeout=30,env=env)
        if run.returncode: raise RuntimeError(run.stdout+run.stderr)
        binaries[label]=binary
    results={label:[] for label in binaries}
    for sample in range(8):
        order=list(binaries)
        if sample%2: order.reverse()
        for label in order:
            run=subprocess.run([str(binaries[label])],capture_output=True,text=True,timeout=30,env=env)
            if run.returncode: raise RuntimeError(run.stdout+run.stderr)
            checksum,elapsed=map(int,run.stdout.split())
            assert checksum==report['expected_checksum'],run.stdout
            if sample: results[label].append(elapsed)
    paired['workloads'][name]={'source':source.read_text(),'kernel_ns':results,
        'median_kernel_ms':{k:statistics.median(v)/1e6 for k,v in results.items()},
        'median_paired_ratio':statistics.median(c/b for b,c in zip(results['baseline'],results['candidate']))}
    print(name,paired['workloads'][name]['median_kernel_ms'],paired['workloads'][name]['median_paired_ratio'],flush=True)
paired['load_end']=os.getloadavg()
paired['script']=Path(__file__).read_text()
Path('/tmp/dewy-source-core/range-index-runtime-paired.json').write_text(json.dumps(paired,indent=2)+'\n')
